// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;
    bool reentered;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0);
        vm.assume(address(this).balance >= a);
        uint beforeC = address(c).balance;
        uint beforeT = address(this).balance;
        try c.deposit{value: a}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        assertTrue(address(c).balance == beforeC && address(this).balance == beforeT);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            try c.withdrawAll() {} catch { return; }
        }
    }
}
